function normalizeRecord(json) {
  if (!json) return null;

  if (Array.isArray(json.records)) {
    return json.records.map(normalizeRecord).filter(Boolean);
  }

  if (json.fields) {
    return {
      id: json.id || json.recordId,
      fields: json.fields,
    };
  }

  const { id, recordId, createdTime, ...rest } = json;

  return {
    id: id || recordId,
    fields: rest,
  };
}

function getRecords(nodeName) {
  const items = $items(nodeName) || [];
  const records = [];

  for (const item of items) {
    const normalized = normalizeRecord(item.json);

    if (Array.isArray(normalized)) {
      records.push(...normalized);
    } else if (normalized) {
      records.push(normalized);
    }
  }

  return records.filter((record) => record.id);
}

function asLinks(value) {
  if (!value) return [];

  if (Array.isArray(value)) {
    return value
      .map((item) => {
        if (typeof item === "string") return item;
        if (item?.id) return item.id;
        if (item?.recordId) return item.recordId;
        return String(item || "");
      })
      .map((item) => item.trim())
      .filter(Boolean);
  }

  if (typeof value === "string") {
    return [value.trim()].filter(Boolean);
  }

  return [];
}

function getString(value) {
  return String(value || "").trim();
}

function getNumber(value) {
  const numberValue = Number(value);
  return Number.isFinite(numberValue) ? numberValue : null;
}

function normalize(value) {
  return getString(value)
    .toLowerCase()
    .replaceAll("ı", "i")
    .replaceAll("ğ", "g")
    .replaceAll("ü", "u")
    .replaceAll("ş", "s")
    .replaceAll("ö", "o")
    .replaceAll("ç", "c")
    .trim();
}

function isPresent(value) {
  const status = normalize(value);
  return status === "geldi" || status === "gec geldi" || status === "geç geldi";
}

function buildGradeSummary(grades) {
  const order = {
    Vize: 1,
    Laboratuvar: 2,
    Final: 3,
    Ortalama: 4,
  };

  return grades
    .sort((a, b) => (order[a.type] || 99) - (order[b.type] || 99))
    .map((grade) => `${grade.type}: ${grade.score}/${grade.maxPoint}`)
    .join(", ");
}

function estimateCurrentPerformanceScore(studentGrades, triggerGradeScore) {
  const averageGrade = studentGrades.find((grade) => grade.type === "Ortalama");

  if (averageGrade && averageGrade.score !== null) {
    return averageGrade.score;
  }

  const validScores = studentGrades
    .map((grade) => grade.score)
    .filter((score) => score !== null);

  if (validScores.length > 0) {
    return Math.round(
      (validScores.reduce((sum, score) => sum + score, 0) / validScores.length) * 100,
    ) / 100;
  }

  return triggerGradeScore || 0;
}

const triggerGrades = getRecords("GET Published Average Grades");
const allGrades = getRecords("GET All Published Grades");
const users = getRecords("GET Users");
const classes = getRecords("GET Classes");
const submissions = getRecords("GET Submissions");
const attendanceRecords = getRecords("GET Attendance Records");
const existingPredictions = getRecords("GET Existing Predictions");

const existingPredictionText = existingPredictions
  .map((prediction) => {
    return [
      getString(prediction.fields.Kaynak_Not_Kodu),
      getString(prediction.fields.Veri_Ozeti),
      getString(prediction.fields.Ozet),
      getString(prediction.fields.Ogretmene_Gosterilecek),
    ].join("\n");
  })
  .join("\n");

const output = [];

for (const triggerGrade of triggerGrades) {
  const studentId = asLinks(triggerGrade.fields.Ogrenci)[0];
  const classId = asLinks(triggerGrade.fields.Sinif)[0];

  if (!studentId || !classId) continue;

  const triggerGradeType = getString(triggerGrade.fields.Not_Turu);
  const triggerGradeScore = getNumber(triggerGrade.fields.Puan);
  const triggerGradeMaxPoint = getNumber(triggerGrade.fields.Maksimum_Puan) || 100;

  if (!triggerGradeType || triggerGradeScore === null) continue;

  const trackingCode = `TAHMIN:NOT:${triggerGrade.id}:ALICI:${studentId}`;

  if (existingPredictionText.includes(trackingCode)) {
    continue;
  }

  const student = users.find((user) => user.id === studentId);
  const classRecord = classes.find((item) => item.id === classId);

  const studentName = getString(student?.fields?.Ad_Soyad) || "Öğrenci";
  const className =
    getString(classRecord?.fields?.Sinif_Adi) ||
    getString(classRecord?.fields?.Ders_Adi) ||
    "Sınıf";

  const studentGrades = allGrades
    .filter((grade) => {
      const gradeStudentId = asLinks(grade.fields.Ogrenci)[0];
      const gradeClassId = asLinks(grade.fields.Sinif)[0];

      return gradeStudentId === studentId && gradeClassId === classId;
    })
    .map((grade) => ({
      id: grade.id,
      type: getString(grade.fields.Not_Turu),
      score: getNumber(grade.fields.Puan),
      maxPoint: getNumber(grade.fields.Maksimum_Puan) || 100,
      date: getString(grade.fields.Tarih),
    }))
    .filter((grade) => grade.type && grade.score !== null);

  const currentPerformanceScore = estimateCurrentPerformanceScore(
    studentGrades,
    triggerGradeScore,
  );

  const studentSubmissions = submissions.filter((submission) => {
    const submissionStudentId = asLinks(submission.fields.Ogrenci)[0];
    const submissionClassId = asLinks(submission.fields.Sinif)[0];

    return submissionStudentId === studentId && submissionClassId === classId;
  });

  const evaluatedSubmissions = studentSubmissions.filter((submission) => {
    return getNumber(submission.fields.Puan) !== null;
  });

  const submissionScores = evaluatedSubmissions
    .map((submission) => getNumber(submission.fields.Puan))
    .filter((score) => score !== null);

  const submissionAverage =
    submissionScores.length > 0
      ? Math.round(
          (submissionScores.reduce((sum, score) => sum + score, 0) /
            submissionScores.length) *
            100,
        ) / 100
      : null;

  const lateSubmissionCount = studentSubmissions.filter((submission) => {
    return Boolean(submission.fields.Gec_Mi);
  }).length;

  const studentAttendance = attendanceRecords.filter((attendance) => {
    const attendanceStudentId = asLinks(attendance.fields.Ogrenci)[0];
    const attendanceClassId = asLinks(attendance.fields.Sinif)[0];

    return attendanceStudentId === studentId && attendanceClassId === classId;
  });

  const presentCount = studentAttendance.filter((attendance) =>
    isPresent(attendance.fields.Durum),
  ).length;

  const attendanceRate =
    studentAttendance.length > 0
      ? Math.round((presentCount / studentAttendance.length) * 10000) / 100
      : null;

  const gradeSummary = buildGradeSummary(studentGrades);

  const dataSummary = [
    `Öğrenci: ${studentName}`,
    `Sınıf: ${className}`,
    `Tahmini mevcut performans puanı: ${currentPerformanceScore}/100`,
    `Tahmini tetikleyen yeni not: ${triggerGradeType} ${triggerGradeScore}/${triggerGradeMaxPoint}`,
    `Not özeti: ${gradeSummary || "Yeterli not verisi yok"}`,
    `Ödev teslim sayısı: ${studentSubmissions.length}`,
    `Değerlendirilmiş ödev ortalaması: ${
      submissionAverage === null ? "Yok" : `${submissionAverage}/100`
    }`,
    `Geç teslim sayısı: ${lateSubmissionCount}`,
    `Yoklama kayıt sayısı: ${studentAttendance.length}`,
    `Devam oranı: ${
      attendanceRate === null ? "Yok" : `${attendanceRate}%`
    }`,
    `Takip kodu: ${trackingCode}`,
  ].join("\n");

  const aiPrompt = `
Sen AkıllıSınıf AI sisteminde çalışan akademik performans tahmin motorusun.

Aşağıdaki öğrenci verilerine göre Türkçe, akademik ve öğretmen tarafından kullanılabilir bir performans tahmini üret.

Bu tahmin özellikle yeni yayınlanan şu nottan sonra oluşturuluyor:
${triggerGradeType}: ${triggerGradeScore}/${triggerGradeMaxPoint}

Veriler:
${dataSummary}

Kurallar:
- Sadece geçerli JSON döndür.
- Markdown kullanma.
- Risk seviyesi sadece şu değerlerden biri olsun: Düşük, Orta, Yüksek, Kritik.
- Risk skoru 0 ile 100 arasında sayı olsun. 0 düşük risk, 100 en yüksek risk.
- Güven düzeyi 0 ile 100 arasında sayı olsun.
- Tahmin kısa ama ciddi akademik dille yazılsın.
- Öğrenciyi suçlayıcı değil, destekleyici dil kullan.
- Eğer sadece tek not varsa, güven düzeyini çok yüksek verme.

JSON formatı:
{
  "risk_seviyesi": "Düşük",
  "risk_skoru": 25,
  "guven_duzeyi": 80,
  "tahmin_ozeti": "metin",
  "guclu_yonler": ["madde"],
  "risk_nedenleri": ["madde"],
  "ogrenci_onerileri": ["madde"],
  "ogretmen_onerileri": ["madde"]
}
`;

  output.push({
    json: {
      trackingCode,
      studentId,
      classId,
      studentName,
      className,
      triggerGradeId: triggerGrade.id,
      triggerGradeType,
      triggerGradeScore,
      triggerGradeMaxPoint,
      averageScore: currentPerformanceScore,
      gradeSummary,
      submissionAverage,
      lateSubmissionCount,
      attendanceRate,
      dataSummary,
      aiPrompt,
    },
  });
}

return output;

