function getString(value) {
  return String(value || "").trim();
}

function getNumber(value, fallback = 0) {
  const numberValue = Number(value);
  return Number.isFinite(numberValue) ? numberValue : fallback;
}

function stripJsonFence(text) {
  return getString(text)
    .replace(/^```json/i, "")
    .replace(/^```/i, "")
    .replace(/```$/i, "")
    .trim();
}

function parseAiJson(text) {
  const clean = stripJsonFence(text);

  try {
    return JSON.parse(clean);
  } catch {
    const match = clean.match(/\{[\s\S]*\}/);
    if (match) {
      try {
        return JSON.parse(match[0]);
      } catch {
        return null;
      }
    }

    return null;
  }
}

function asListText(value) {
  if (Array.isArray(value)) {
    return value.map((item) => `- ${getString(item)}`).join("\n");
  }

  return getString(value);
}

function clamp(numberValue, min, max) {
  return Math.max(min, Math.min(max, numberValue));
}

const inputItems = $items("Prepare Prediction Inputs");
const aiItems = $items("OpenRouter AI Prediction");

const output = [];

for (let index = 0; index < aiItems.length; index += 1) {
  const source = inputItems[index]?.json || {};
  const aiResponse = aiItems[index]?.json || {};

  const aiText =
    aiResponse.choices?.[0]?.message?.content ||
    aiResponse.body?.choices?.[0]?.message?.content ||
    "";

  const parsed = parseAiJson(aiText) || {};

  const riskLevel = getString(parsed.risk_seviyesi) || "Orta";
  const riskScore = clamp(getNumber(parsed.risk_skoru, 50), 0, 100);
  const confidence = clamp(getNumber(parsed.guven_duzeyi, 70), 0, 100);

  const averageScore = getNumber(source.averageScore, 0);

  // Simple pass probability estimate:
  // higher average + lower risk = higher probability
  const passProbability = clamp(
    Math.round((averageScore * 0.7 + (100 - riskScore) * 0.3) * 100) / 100,
    0,
    100,
  );

  const predictionSummary =
    getString(parsed.tahmin_ozeti) ||
    "AI performans tahmini oluşturuldu.";

  const studentAdvice =
    asListText(parsed.ogrenci_onerileri) ||
    "- Ders tekrarlarını düzenli yapması önerilir.\n- Eksik konularını öğretmeniyle paylaşması önerilir.";

  const teacherAdvice =
    asListText(parsed.ogretmen_onerileri) ||
    "- Öğrencinin gelişimi düzenli takip edilmelidir.\n- Gerekirse kısa müdahale planı oluşturulmalıdır.";

  const riskReasons =
    asListText(parsed.risk_nedenleri) ||
    "- Belirgin risk nedeni model tarafından belirtilmedi.";

  const strengths =
    asListText(parsed.guclu_yonler) ||
    "- Güçlü yön bilgisi model tarafından belirtilmedi.";

  const teacherVisibleText = [
    "AI Tahmin Özeti:",
    predictionSummary,
    "",
    "Güçlü Yönler:",
    strengths,
    "",
    "Risk Nedenleri:",
    riskReasons,
    "",
    "Öğretmen Önerileri:",
    teacherAdvice,
    "",
    "Veri Özeti:",
    source.dataSummary,
  ].join("\n");

  const studentVisibleText = [
    "Performans Tahmini:",
    predictionSummary,
    "",
    "Öğrenciye Öneriler:",
    studentAdvice,
  ].join("\n");

  output.push({
    json: {
      fields: {
        Tahmin_Adi: `${source.studentName} - ${source.className} - AI Performans Tahmini`,
        Ogrenci: [source.studentId],
        Sinif: [source.classId],
        Ozet: predictionSummary,
        Tahmini_Donem_Notu: averageScore,
        Gecme_Olasiligi: passProbability,
        Risk_Seviyesi: riskLevel,
        Aciklama_1: strengths,
        Aciklama_2: riskReasons,
        Aciklama_3: teacherAdvice,
        Ogrenciye_Gosterilecek: studentVisibleText,
        Ogretmene_Gosterilecek: teacherVisibleText,
        Tahmin_Tarihi: new Date().toISOString().slice(0, 10),
        Gecerli_Mi: true,
        Kaynak_Not_Kodu: source.trackingCode,
      },
      trackingCode: source.trackingCode,
      studentName: source.studentName,
      className: source.className,
      riskLevel,
      riskScore,
      confidence,
      passProbability,
    },
  });
}

return output;
